import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.logging.*;

public class ReportServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger(ReportServlet.class.getName());

    // Connection pool managed by container
    private DataSource getDataSource() throws Exception {
        javax.naming.InitialContext ctx = new javax.naming.InitialContext();
        return (DataSource) ctx.lookup("java:comp/env/jdbc/ReportsDB");
    }

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {

        String reportType = req.getParameter("type");
        String startDate = req.getParameter("start");
        String endDate = req.getParameter("end");
        String department = req.getParameter("dept");

        // Validate report type against allowed list
        if (!isValidReportType(reportType)) {
            resp.sendError(400, "Invalid report type");
            return;
        }

        // Basic date format check (not sufficient for SQL safety)
        if (startDate == null || endDate == null) {
            resp.sendError(400, "Date range required");
            return;
        }

        // Department filter - user controlled, concatenated into query
        String query = buildReportQuery(reportType, startDate, endDate, department);

        try (Connection conn = getDataSource().getConnection();
             Statement stmt = conn.createStatement();
             ResultSet rs = stmt.executeQuery(query)) {

            resp.setContentType("application/json");
            PrintWriter out = resp.getWriter();
            out.print("[\n");
            boolean first = true;
            ResultSetMetaData meta = rs.getMetaData();
            int cols = meta.getColumnCount();

            while (rs.next()) {
                if (!first) out.print(",\n");
                first = false;
                out.print("  {");
                for (int i = 1; i <= cols; i++) {
                    if (i > 1) out.print(", ");
                    out.print("\"" + meta.getColumnLabel(i) + "\": ");
                    out.print("\"" + escapeJson(rs.getString(i)) + "\"");
                }
                out.print("}");
            }
            out.print("\n]");

        } catch (Exception e) {
            log.warning("Report query failed: " + e.getMessage());
            resp.sendError(500, "Report generation failed");
        }
    }

    private boolean isValidReportType(String type) {
        return type != null && (type.equals("sales") || type.equals("inventory") 
               || type.equals("hr") || type.equals("finance"));
    }

    private String buildReportQuery(String type, String start, String end, String dept) {
        String table = "report_" + type; // type is validated above
        StringBuilder sb = new StringBuilder();
        sb.append("SELECT * FROM ").append(table);
        sb.append(" WHERE report_date BETWEEN '").append(start).append("' AND '").append(end).append("'");

        if (dept != null && !dept.isEmpty()) {
            // NOTE: department is user-supplied and not sanitized
            sb.append(" AND department = '").append(dept).append("'");
        }

        sb.append(" ORDER BY report_date DESC LIMIT 1000");
        return sb.toString();
    }

    private String escapeJson(String val) {
        if (val == null) return "null";
        return val.replace("\\", "\\\\").replace("\"", "\\\"").replace("\n", "\\n");
    }
}
